        _root_const = null;
        _in_subtree = false;
        _baseSvg = null;
        _svgGroup = null;
        _geomLayers = null;
        _drawnGeom = null;
        _hitNodes = [];
        _nodeIndex = null;
        _hoverNode = null;
        _overviewGroup = null;
        _overviewContent = null;
        _overviewViewport = null;
        _overviewMap = null;
