    function layoutButtonClicked() {
        _state.circularDisplay = getCheckboxValue(LAYOUT_CIRC_BUTTON);
        _state.unrootedDisplay = getCheckboxValue(LAYOUT_UNROOTED_BUTTON);
        if (_treeData && _treeData.rooted === false) {
            populateSearchMenus();   // the root-measured search fields go and come with the unrooted layout
            search0();
            search1();
        }
        if (radialDisplay() && ((_state.showDomainArchitectures && _basicTreeProperties.domainArchitectures)
            || (_state.showGenes && _basicTreeProperties.geneRegions))) {
            // the domain boxes and gene arrows ride the tips' spokes, so the labels must too
            _radialLabelsHorizontal = false;
        }
        syncZoomRowButtons();
        afterUpdate(syncDomainControls);   // the track width buttons follow the layout's own width
        afterUpdate(syncGeneControls);
        zoomToFit();
    }

    // While the circular layout is on, X-/X+ wear the desktop's rotate faces
    // and rotate the display; in the rectangular layout they are the plain
    // horizontal zoom pair. Same buttons, same bindings -- only the face and
    // the meaning change with the layout.
    function syncZoomRowButtons() {
        // layout-restricted controls, as on the desktop: unrooted has no
        // common label edge to align to and no even row spacing to auto-hide
        // against; an alignment / time axis is inherently horizontal. Synced
        // BEFORE the zoom-row early return, and (via updateButtonEnabledState)
        // on every render, so subtree switches keep them honest.
        // WHICH of the two phylogram buttons is dead depends on the layout,
        // and it is the one the layout CANNOT do -- not the one it always
        // does. Circular always carries its external labels out to a common
        // ring on dashed connectors, whatever is chosen, so the circular
        // phylogram IS the aligned one: the unavailable option there is the
        // UNALIGNED phylogram. Unrooted is the other way round -- it has no
        // common edge to align to, so what it cannot do is align.
        //
        // (Greying the aligned button in circular was the first attempt, on
        // the grounds that picking it changed nothing. True, but backwards:
        // it disabled the button that describes what the layout does and left
        // live the one it cannot do, and the panel then showed "phylogram"
        // selected over a picture whose labels are plainly aligned. Christian
        // spotted the inconsistency, 2026-09-27.)
        let measured = _basicTreeProperties.branchLengths === true;
        let phyBtn = byId(PHYLOGRAM_BUTTON);
        if (phyBtn) {
            phyBtn.disabled = !measured || _state.circularDisplay;
            phyBtn.title = PHYLOGRAM_WHAT;
        }
        let alignBtn = byId(PHYLOGRAM_ALIGNED_BUTTON);
        if (alignBtn) {
            alignBtn.disabled = !measured || _state.unrootedDisplay;
            alignBtn.title = PHYLOGRAM_ALIGNED_WHAT;
        }
        // Which button is SHOWN as chosen is layout-dependent too, and this
        // was only re-synced when the display type changed -- so switching
        // layout left the previous layout's answer on the screen.
        setDisplayTypeButtons();
        // Auto-hide Labels stays live in every layout. It used to be greyed out
        // in unrooted, where the every-k-th tip-label decimation does not run --
        // but it also governs the crowded branch-data rule, and now the
        // unrooted tip-label rule, both of which do run there, so greying it
        // out left the user unable to switch off what they could see.
        let msaCb = byId(MSA_CB);
        if (msaCb) {
            msaCb.disabled = radialDisplay();
        }
        let msaLogoCb = byId(MSA_LOGO_CB);
        if (msaLogoCb) {
            // nothing to summarize while the alignment itself is not drawn
            msaLogoCb.disabled = radialDisplay() || _state.showMsa !== true;
        }
        let heatCb = byId(HEATMAP_CB);
        if (heatCb) {
            // circular draws the columns as rings; only unrooted cannot
            heatCb.disabled = _state.unrootedDisplay === true;
        }
        syncHeatmapControls();
        let axisCb = byId(SCALE_AXIS_CB);
        if (axisCb) {
            // circular draws it along the gap; unrooted cannot, and a
            // cladogram has nothing to measure
            axisCb.disabled = _state.unrootedDisplay === true || _state.phylogram !== true;
        }
        let gridCb = byId(SCALE_GRID_CB);
        if (gridCb) {
            // grid lines hang off the scale axis: no axis, nothing to grid
            gridCb.disabled = _state.unrootedDisplay === true || _state.phylogram !== true
                || _state.showScaleAxis !== true;
        }
        let barCb = byId(SCALE_BAR_CB);
        if (barCb) {
            // a cladogram has nothing to measure, and under the axis the bar
            // has given way; every layout can carry it otherwise
            barCb.disabled = _state.phylogram !== true || scaleAxisShown();
        }
        let minus = byId(ZOOM_OUT_X);
        let plus = byId(ZOOM_IN_X);
        let expandV = byId(ZOOM_TO_EXPAND_Y);
        let fitW = byId(FIT_WIDTH_BUTTON);
        if (!minus || !plus || !expandV || !fitW) {
            return;
        }
        let yIn = byId(ZOOM_IN_Y);
        let yOut = byId(ZOOM_OUT_Y);
        if (radialDisplay()) {
            // both axes of a circle are its one diameter, so the Y pair
            // becomes the plain +/- zoom, as on the desktop
            if (yIn) {
                yIn.value = '+';
                yIn.title = 'zoom in (or mousewheel over the tree)';
            }
            if (yOut) {
                yOut.value = '-';
                yOut.title = 'zoom out (or mousewheel over the tree)';
            }
            minus.innerHTML = makeGlyph('rotate_ccw');
            minus.title = 'rotate counter-clockwise';
            plus.innerHTML = makeGlyph('rotate_cw');
            plus.title = 'rotate clockwise';
            // as on the desktop: no vertical expansion in circular, and the
            // fit-width slot -- redundant with fit there, a circle has just
            // its one diameter -- becomes the label-direction flip. Its face
            // shows the direction a click switches TO, its tooltip the
            // current one.
            expandV.disabled = true;
            fitW.disabled = false;
            fitW.innerHTML = makeGlyph(_radialLabelsHorizontal ? 'labels_radial' : 'labels_horizontal');
            fitW.title = 'node labels: ' + (_radialLabelsHorizontal ? 'horizontal' : 'radial')
                + ' -- click to flip';
        } else {
            if (yIn) {
                yIn.value = 'Y+';
                yIn.title = 'zoom in vertically (or Shift+mousewheel)';
            }
            if (yOut) {
                yOut.value = 'Y-';
                yOut.title = 'zoom out vertically (or Shift+mousewheel)';
            }
            minus.textContent = 'X-';
            minus.title = 'zoom out horizontally (or Shift+Alt+mousewheel)';
            plus.textContent = 'X+';
            plus.title = 'zoom in horizontally (or Shift+Alt+mousewheel)';
            expandV.disabled = false;
            fitW.disabled = false;
            fitW.innerHTML = makeGlyph('fit_width');
            fitW.title = 'fit the tree to the window width, keeping the current vertical zoom';
        }
    }

