    // Post-processes a control panel once: moves its sections into a scrolling
    // body under the fixed header, adds a hide/show toggle to the header, and
    // makes each titled section (a fieldset with a legend) collapse on click.
    // Together these keep the panel from running off the screen and let it be
    // folded away entirely.
    function enhancePanel(panel, title) {
        if (!panel || panel.dataset.aptxEnhanced) {
            return;
        }
        panel.dataset.aptxEnhanced = '1';

        let header = panel.querySelector('.' + PROG_NAME);

        // Panels without their own header (the legend/visualization panel) get
        // one built from the given title, so they gain the same header bar and
        // hide button as the main control panel.
        if (!header && title) {
            header = document.createElement('div');
            header.className = PROG_NAME;
            let titleEl = document.createElement('span');
            titleEl.className = 'aptx-panel-title';
            titleEl.textContent = title;
            header.appendChild(titleEl);
            panel.insertBefore(header, panel.firstChild);
        }

        // Move everything after the header into a scrolling body.
        let body = document.createElement('div');
        body.className = 'aptx-body';
        let node = header ? header.nextSibling : panel.firstChild;
        while (node) {
            let next = node.nextSibling;
            body.appendChild(node);
            node = next;
        }
        panel.appendChild(body);

        // Header actions: the light/dark switch (main panel only) and the
        // whole-panel hide/show toggle, grouped at the right of the header.
        if (header) {
            let actions = document.createElement('div');
            actions.className = 'aptx-actions';

            let infoBtn = document.createElement('button');
            infoBtn.type = 'button';
            // NOT aptx-theme-btn: applyPanelTheme repaints the innerHTML of
            // every element carrying that class with the sun/moon, so
            // borrowing it for the chrome replaced this glyph the instant a
            // theme was applied. The two share their styling through the CSS
            // selector instead, which is all the class was wanted for.
            infoBtn.className = 'aptx-info-btn';
            infoBtn.title = 'Tree properties and statistics ('
                + (IS_MAC ? '\u2318I' : 'Ctrl+I') + ')';
            infoBtn.setAttribute('aria-label', 'Tree properties and statistics');
            infoBtn.innerHTML = makeGlyph('info');
            infoBtn.addEventListener('click', function (e) {
                e.stopPropagation();
                showTreePropertiesDialog();
            });
            actions.appendChild(infoBtn);

            let sheetBtn = document.createElement('button');
            sheetBtn.type = 'button';
            sheetBtn.className = 'aptx-info-btn';
            sheetBtn.title = 'Control panel: what each control does';
            sheetBtn.setAttribute('aria-label', 'Control panel cheat sheet');
            sheetBtn.innerHTML = makeGlyph('cheat_sheet');
            sheetBtn.addEventListener('click', function (e) {
                e.stopPropagation();
                showCheatSheetDialog();
            });
            actions.appendChild(sheetBtn);

            let progName = header.querySelector('.' + PROGNAMELINK);
            if (progName) {
                // Clicking the title used to navigate away to the project site;
                // it opens the About box, which links there among other places.
                progName.addEventListener('click', function (e) {
                    e.stopPropagation();
                    showAboutDialog();
                });
                // config warnings are recorded before this header exists
                syncDoctorDot();
                // ... and a library can arrive after it (see syncDoctorDot)
                let panel = header.closest('.aptx-panel');
                if (panel) {
                    panel.addEventListener('pointerenter', syncDoctorDot);
                }
                if (document.readyState !== 'complete') {
                    window.addEventListener('load', syncDoctorDot, {once: true});
                }

                let themeBtn = document.createElement('button');
                themeBtn.type = 'button';
                themeBtn.className = 'aptx-theme-btn';
                themeBtn.title = 'Switch between light and dark';
                themeBtn.innerHTML = panelThemeIcon();
                themeBtn.addEventListener('click', function (e) {
                    e.stopPropagation();
                    togglePanelTheme();
                });
                actions.appendChild(themeBtn);
            }

            let toggle = document.createElement('button');
            toggle.type = 'button';
            toggle.className = 'aptx-hide-btn';
            toggle.title = 'Hide / show the controls';
            toggle.textContent = '–';
            toggle.addEventListener('click', function (e) {
                e.stopPropagation();
                let hidden = panel.classList.toggle('aptx-hidden');
                toggle.textContent = hidden ? '+' : '–';
            });
            actions.appendChild(toggle);

            header.appendChild(actions);
        }

        // Collapsible sections: wrap each titled fieldset's content in a body
        // element (so collapsing hides everything under the legend, including
        // bare text labels like the slider captions) and toggle it via the legend.
        let initiallyOpen = [];
        let fieldsets = body.querySelectorAll('fieldset');
        for (let i = 0; i < fieldsets.length; ++i) {
            let fieldset = fieldsets[i];
            let legend = fieldset.querySelector('legend');
            if (!legend) {
                continue;
            }
            let fsBody = document.createElement('div');
            fsBody.className = 'aptx-fieldset-body';
            let n = legend.nextSibling;
            while (n) {
                let next = n.nextSibling;
                fsBody.appendChild(n);
                n = next;
            }
            fieldset.appendChild(fsBody);
            legend.classList.add('aptx-legend-toggle');
            let name = legend.textContent.trim();
            if (sectionFoldedInitially(name)) {
                fieldset.classList.add('aptx-collapsed');
            } else {
                initiallyOpen.push(name);
            }
            legend.addEventListener('click', function () {
                let opened = !fieldset.classList.toggle('aptx-collapsed');
                loadPanelSections()[name] = !opened;
                if (opened) {
                    _panelOpenOrder.set(name, ++_panelOpenSeq);
                    fitPanelSections(panel, name);
                }
                savePanelSections();
                // a folded section's controls are off the screen, so they
                // leave the cheat sheet: it describes what the panel is
                // showing, and folding does not go through a tree render
                refreshCheatSheet();
            });
        }
        // What arrived open counts as opened, oldest at the BOTTOM: a panel is
        // read top-down, so when a short window forces something to fold on
        // arrival it should be the last section rather than the one describing
        // the tree at the top. Anything the user opens later is newer than all
        // of these, and folds after them.
        for (let i = initiallyOpen.length - 1; i >= 0; --i) {
            _panelOpenOrder.set(initiallyOpen[i], ++_panelOpenSeq);
        }
        // A remembered set of open sections can be taller than this window,
        // so the fit rule runs once on arrival too -- with no section to
        // spare, since the user opened none of them just now.
        fitPanelSections(panel, null);

        // ... and again whenever the room changes. The panel is held to its
        // container's height, so a window dragged shorter (or a host resizing
        // the div around us) can push an arrangement that fitted a moment ago
        // into a scrollbar. Watching the CONTAINER, not the panel: folding a
        // section changes the panel's height and would re-enter the observer.
        // One-way on purpose -- growing the window back does NOT reopen what
        // was folded. What is open is the user's choice; only running out of
        // room may overrule it, and then only far enough to fit.
        if (typeof ResizeObserver !== 'undefined' && panel.parentElement) {
            new ResizeObserver(function () {
                fitPanelSections(panel, null);
            }).observe(panel.parentElement);
        }

        // Apply the current light/dark choice to this (and every) panel.
        applyPanelTheme();
    }

    // Safely binds an event handler to an element by id (replaces jQuery
    // $('#' + id).click/.on/.bind/.mousedown/.keyup(...)). A missing element is
    // a no-op, matching jQuery's behavior on an empty selection.
    function on(id, evt, handler) {
        let el = byId(id);
        if (el) {
            el.addEventListener(evt, handler);
        }
    }

    // Press-and-hold binding for a button by id (replaces jQuery
    // $('#' + id).mousedown(down).bind('mouseup mouseleave', up)): the down
    // handler fires on press, the up handler on release or when the pointer
    // leaves the button.
    function onHold(id, downHandler, upHandler) {
        let el = byId(id);
        if (el) {
            el.addEventListener('mousedown', downHandler);
            el.addEventListener('mouseup', upHandler);
            el.addEventListener('mouseleave', upHandler);
            // Keyboard activation: Enter or Space raises a click with detail 0
            // (a real mouse click carries a click count). One step per press,
            // no repeat -- and the mouse path never reaches this.
            el.addEventListener('click', function (event) {
                if (event.detail === 0) {
                    downHandler();
                    upHandler();
                }
            });
        }
    }

    // Maps a d3 v3 symbol-type name (string) to a d3 v7 symbol-type constant.
    // v7 dropped the separate up/down triangles, so both map to symbolTriangle.
    function d3SymbolType(shapeName) {
        switch (shapeName) {
            case 'square':
                return d3.symbolSquare;
            case 'diamond':
                return d3.symbolDiamond;
            case 'triangle-up':
            case 'triangle-down':
            case 'triangle':
                return d3.symbolTriangle;
            case 'cross':
                return d3.symbolCross;
            case 'star':
                return d3.symbolStar;
            case 'wye':
                return d3.symbolWye;
            case 'circle':
            default:
                return d3.symbolCircle;
        }
    }

    function getSliderValue(e) {
        return parseFloat(e.target.value);
    }

    function setSliderValue(id, value) {
        let el = document.getElementById(id);
        if (el) {
            el.value = value;
        }
    }

    // Initializes a native range input (replaces the former jQuery UI slider).
    // The 'input' event fires continuously while dragging, covering what jQuery
    // UI split into its 'slide' and 'change' callbacks.
    function initSlider(id, min, max, step, value, onInput) {
        let el = document.getElementById(id);
        if (el) {
            el.min = min;
            el.max = max;
            el.step = step;
            el.value = value;
            el.addEventListener('input', onInput);
        }
    }

    // Shows a modal popup with the given HTML content (replaces the former
    // jQuery UI dialog used for the node/sequence data popups). Only one such
    // dialog exists at a time; opening a new one removes the previous. Uses the
    // native <dialog> element, so Escape and the close button both dismiss it.
    // With mono set the body is shown as a preformatted monospaced block, which
    // is what a FASTA sequence needs; otherwise it is laid out as label/value.
    // Content arrives as "Label: value" lines separated by <br>. Setting the
    // label part apart makes a wall of such lines scannable. Lines without a
    // label (a heading like "Taxonomy", or a FASTA sequence) are left alone.
    // The unrooted layout of a tree its file declares unrooted (phyloXML
    // rooted="false", Nexus [&U]; a plain Newick tree declares nothing). The
    // unrooted layout of a rooted tree still has its root.
    function unrootedContext() {
        return _state.unrootedDisplay === true && !!_treeData && _treeData.rooted === false;
    }

    // The tips on each side of an internal node of an unrooted tree, one
    // count per neighbour, smallest first: what "tips below" becomes when
    // there is no below.
    function tipsAround(d) {
        let sides = d.children.map(function (c) {
            return forester.calcSumOfAllExternalDescendants(c);
        });
        let below = sides.reduce(function (a, b) {
            return a + b;
        }, 0);
        let all = forester.calcSumOfAllExternalDescendants(forester.getTreeRoot(_treeData));
        if (all > below) {
            sides.push(all - below);
        }
        return sides.sort(function (a, b) {
            return a - b;
        });
    }

    // The node's data as the hover tooltip and the "Display Node Data" dialog
    // both show it -- ONE builder, because they used to be two near-copies
    // and carried the same two bugs twice (a bare "Date: " line whenever a
    // date had no description, and "Distribution: " printed before its
    // description was checked).
    //
    // Order, as the desktop lays it out: first the node itself -- Name,
    // Distance to parent, Date, Distribution, Depth, Tips below -- then its
    // confidences, then the headed sections. Every row is either in that
    // leading block or under a heading, so nothing reads as a stray tail of
    // the section above it. markUpDataLabels() renders the result: a line
    // shaped "Key: value" is a row, anything else a heading, and a leading
    // "- " marks a row as a section's sub-entry.
    //
    // A tree its file declares unrooted, shown in the unrooted layout, has no
    // root to measure from (unrootedContext): an internal node shows no
    // distance to parent, depth or tips below but the tips on each of its
    // sides, and a tip's branch is just its branch length -- as on the desktop.
    function nodeDataText(d) {
        let text = '';
        let unrooted = unrootedContext();
        if (d.name) {
            text += 'Name: ' + d.name + '<br>';
        }
        if (d.branch_length !== undefined && d.branch_length !== null
            && !(unrooted && d.children)) {
            text += (unrooted ? 'Branch length: ' : 'Distance to parent: ') + d.branch_length + '<br>';
        }
        let date = dateText(d.date);
        if (date) {
            text += 'Date: ' + date + '<br>';
        }
        if (d.distributions) {
            for (let i = 0; i < d.distributions.length; ++i) {
                // only a distribution that has something to say gets a row
                if (d.distributions[i].desc) {
                    text += 'Distribution: ' + d.distributions[i].desc + '<br>';
                }
            }
        }
        if (!unrooted) {
            text += 'Depth: ' + forester.calcDepth(d) + '<br>';
            if (d.children) {
                text += 'Tips below: ' + forester.calcSumOfAllExternalDescendants(d) + '<br>';
            }
        } else if (d.children) {
            text += 'Tips around: ' + tipsAround(d).join(' · ') + '<br>';
        }
        if (d.confidences) {
            for (let i = 0; i < d.confidences.length; ++i) {
                let c = d.confidences[i];
                text += (c.type ? 'Confidence [' + c.type + ']: ' : 'Confidence: ') + c.value + '<br>';
                if (c.stddev) {
                    text += '- stdev: ' + c.stddev + '<br>';
                }
            }
        }
        if (d.taxonomies) {
            for (let i = 0; i < d.taxonomies.length; ++i) {
                let tx = d.taxonomies[i];
                text += 'Taxonomy<br>';
                if (tx.id) {
                    text += (tx.id.provider ? '- Id [' + tx.id.provider + ']: ' : '- Id: ') + tx.id.value + '<br>';
                }
                if (tx.code) {
                    text += '- Code: ' + tx.code + '<br>';
                }
                if (tx.scientific_name) {
                    text += '- Scientific name: ' + tx.scientific_name + '<br>';
                }
                if (tx.common_name) {
                    text += '- Common name: ' + tx.common_name + '<br>';
                }
                if (tx.rank) {
                    text += '- Rank: ' + tx.rank + '<br>';
                }
            }
        }
        if (d.sequences) {
            for (let i = 0; i < d.sequences.length; ++i) {
                let s = d.sequences[i];
                text += 'Sequence<br>';
                if (s.accession) {
                    text += (s.accession.source ? '- Accession [' + s.accession.source + ']: ' : '- Accession: ')
                        + s.accession.value + '<br>';
                    if (s.accession.comment) {
                        text += '-- comment: ' + s.accession.comment + '<br>';
                    }
                }
                if (s.symbol) {
                    text += '- Symbol: ' + s.symbol + '<br>';
                }
                if (s.name) {
                    text += '- Name: ' + s.name + '<br>';
                }
                if (s.gene_name) {
                    text += '- Gene name: ' + s.gene_name + '<br>';
                }
                if (s.location) {
                    text += '- Location: ' + s.location + '<br>';
                }
                if (s.type) {
                    text += '- Type: ' + s.type + '<br>';
                }
                // The annotations, which this dialog never listed and which a
                // gene's family lives in (<annotation ref="pgfam:...">): the
                // ref, with the description when there is one.
                (s.annotations || []).forEach(function (an) {
                    if (!an || (!an.ref && !an.desc)) {
                        return;
                    }
                    text += '- Annotation: ' + (an.ref ? an.ref + (an.desc ? ' (' + an.desc + ')' : '') : an.desc) + '<br>';
                });
                // The domain architecture, which phyloXML has always carried
                // and this dialog has never shown: a reader could find a node
                // by searching for one of its domains -- forester indexes them
                // as the "Domain" search field -- and then see nothing about it
                // here. Listed in POSITION order rather than file order, since
                // an architecture is a line along the protein and reading it
                // out of order tells you nothing.
                let da = s.domain_architecture;
                if (da && da.domains && da.domains.length > 0) {
                    text += '- Domain architecture: '
                        + (da.length ? da.length + ' aa, ' : '')
                        + da.domains.length + (da.domains.length === 1 ? ' domain' : ' domains')
                        + '<br>';
                    da.domains.slice().sort(function (a, b) {
                        return (a.from - b.from) || (a.to - b.to);
                    }).forEach(function (dom) {
                        let name = dom.name || '(unnamed)';
                        let span = (dom.from !== undefined && dom.to !== undefined)
                            ? dom.from + '-' + dom.to : '';
                        // the confidence on a domain is its e-value; an
                        // explicit 0 is a real score, so test for undefined
                        let ev = (dom.confidence !== undefined && dom.confidence !== null)
                            ? ' (E=' + dom.confidence + ')' : '';
                        text += '-- ' + name + ': ' + span + ev + '<br>';
                    });
                }
            }
        }
        if (d.events) {
            let ev = d.events;
            text += 'Events<br>';
            if (ev.type && ev.type.length > 0) {
                text += '- Type: ' + ev.type + '<br>';
            }
            if (ev.duplications && ev.duplications > 0) {
                text += '- Duplications: ' + ev.duplications + '<br>';
            }
            if (ev.speciations && ev.speciations > 0) {
                text += '- Speciations: ' + ev.speciations + '<br>';
            }
            if (ev.losses && ev.losses > 0) {
                text += '- Losses: ' + ev.losses + '<br>';
            }
        }
        if (d.properties && d.properties.length > 0) {
            // Named as the Color-by menu names them ("Host Group", not
            // "BVBRC:host_group"). style:* refs are the desktop's visual-style
            // namespace -- how a node is drawn, not what it is -- and are
            // skipped, as the Color-by menu skips them.
            let rows = '';
            for (let i = 0; i < d.properties.length; ++i) {
                let pr = d.properties[i];
                if (pr.ref && pr.value && pr.ref.indexOf('style:') !== 0) {
                    rows += '- ' + forester.propertyDisplayName(pr.ref) + ': '
                        + pr.value + (pr.unit ? ' ' + pr.unit : '') + '<br>';
                }
            }
            if (rows) {
                text += 'Metadata<br>' + rows;
            }
        }
        return text;
    }

    // One line for a node's date, as the desktop writes it: the value, its
    // range, its unit and its description folded together -- "6.5 [5 - 8]
    // mya (split)" -- or just the description when that is all there is.
    // Null when there is nothing to say, so no bare "Date: " ever appears.
    function dateText(date) {
        if (!date) {
            return null;
        }
        let hasValue = typeof date.value === 'number';
        // the same predicate the bars use: a bound pair that differs only by
        // floating-point noise is one number printed twice, and reading it as a
        // range put "[12.059999999999942 - 12.059999999999949]" in the tooltip
        let hasRange = forester.isGenuineDateInterval(date);
        let s = hasValue ? String(date.value) : '';
        if (hasRange) {
            s += ' [' + date.minimum + ' - ' + date.maximum + ']';
        }
        if ((hasValue || hasRange) && date.unit) {
            s += ' ' + date.unit;
        }
        s = s.trim();
        if (date.desc) {
            s = s ? s + ' (' + date.desc + ')' : date.desc;
        }
        return s || null;
    }

    function markUpDataLabels(escaped) {
        return escaped.split('<br>').map(function (line) {
            if (!line.trim()) {
                return '';
            }
            let m = /^(\s*-*\s*[^:<]{1,40}?):\s(.*)$/.exec(line);
            if (!m) {
                // no label: a section heading such as "Taxonomy" or "Sequence"
                return '<div class="aptx-dialog-head">' + line.trim() + '</div>';
            }
            // the source marks sub-entries with leading dashes; the layout shows
            // that relationship now, so the dashes only add noise
            let key = m[1].replace(/^[\s-]+/, '');
            return '<div class="aptx-dialog-line"><span class="aptx-dialog-key">' + key
                + '</span><span class="aptx-dialog-val">' + m[2] + '</span></div>';
        }).join('');
    }

    // The shell every modal shares: title bar with a close button, a body, the
    // panel's light/dark choice, and removal on close. Returns the body for the
    // caller to fill. Only one dialog of a given id exists at a time.
    // A "working" card over the tree area. Shown while a big tree's first draw
    // is deferred, so the user sees the program is busy rather than a page that
    // has stopped responding -- which is what a 10-second synchronous draw
    // looks like from the outside.
    function showBusy(container, text, sub) {
        container.querySelectorAll(':scope > .aptx-busy').forEach(function (b) {
            b.remove();
        });
        let busy = document.createElement('div');
        busy.className = 'aptx-busy';
        if (_panelTheme) {
            busy.classList.add('aptx-' + _panelTheme);
        }
        busy.setAttribute('role', 'status');
        busy.setAttribute('aria-live', 'polite');
        let card = document.createElement('div');
        card.className = 'aptx-busy-card';
        let dot = document.createElement('span');
        dot.className = 'aptx-busy-dot';
        let label = document.createElement('span');
        label.textContent = text;
        card.appendChild(dot);
        card.appendChild(label);
        if (sub) {
            let s = document.createElement('span');
            s.className = 'aptx-busy-sub';
            s.textContent = sub;
            card.appendChild(s);
        }
        busy.appendChild(card);
        container.appendChild(busy);
        return busy;
    }

    function hideBusy() {
        if (_container) {
            _container.querySelectorAll('.aptx-busy').forEach(function (b) {
                b.remove();
            });
        }
    }

    // Run fn after the browser has had a chance to PAINT. A plain setTimeout
    // does not promise that; rAF fires just before a paint, so a timeout queued
    // from inside it lands just after one. A hidden tab may never fire rAF at
    // all, so a fallback timer guarantees the work still happens.
    function afterPaint(fn) {
        let done = false;
        function go() {
            if (!done) {
                done = true;
                fn();
            }
        }
        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(function () {
                setTimeout(go, 0);
            });
        }
        setTimeout(go, 150);
    }

    // Record how long a redraw that began at `start` took, up to the frame
    // that painted it: the second animation frame from here runs after that
    // paint, whether the redraw ran in a frame or just after one. `share`
    // scales the measurement (a first draw stands in for a redraw at a
    // third, see launchInto). A hidden tab runs no frames, and the last
    // estimate stands.
    function timeRedraw(start, seq, share) {
        if (typeof requestAnimationFrame !== 'function') {
            return;
        }
        requestAnimationFrame(function () {
            requestAnimationFrame(function () {
                if (seq === _launchSeq) {
                    _redrawMs = (performance.now() - start) * share;
                }
            });
        });
    }

    function makeDialogShell(id, title, width) {
        let existing = document.getElementById(id);
        if (existing) {
            existing.remove();
        }
        let dialog = document.createElement('dialog');
        dialog.id = id;
        dialog.className = 'aptx-dialog';
        if (_panelTheme) {
            dialog.classList.add('aptx-' + _panelTheme); // follow the panel's light/dark choice
        }
        dialog.style.width = width + 'px';

        let titlebar = document.createElement('div');
        titlebar.className = 'aptx-dialog-title';
        let name = document.createElement('span');
        name.className = 'aptx-dialog-name';
        name.textContent = title;
        titlebar.appendChild(name);

        let closeButton = document.createElement('button');
        closeButton.type = 'button';
        closeButton.className = 'aptx-dialog-close';
        closeButton.title = 'Close';
        closeButton.setAttribute('aria-label', 'Close');
        closeButton.textContent = '✕';
        closeButton.addEventListener('click', function () {
            dialog.close();
        });
        titlebar.appendChild(closeButton);

        let body = document.createElement('div');
        body.className = 'aptx-dialog-body';

        dialog.appendChild(titlebar);
        dialog.appendChild(body);
        document.body.appendChild(dialog);
        dialog.addEventListener('close', function () {
            dialog.remove();
        });
        return {dialog: dialog, body: body};
    }

    function showNodeDataDialog(title, htmlContent, mono, width, height) {
        let shell = makeDialogShell(NODE_DATA, title, width);
        if (mono) {
            shell.body.classList.add('aptx-dialog-mono');
        }
        // htmlContent is built from tree-file text with <br> separators; escape
        // everything else so a crafted name / property value cannot inject markup.
        let escaped = escapeHtmlKeepBreaks(htmlContent);
        shell.body.innerHTML = mono ? escaped : markUpDataLabels(escaped);
        shell.body.style.maxHeight = height + 'px';
        shell.dialog.showModal();
    }

    // ===================== Tree properties =====================
    // What the tree IS and what it carries: the desktop's View > Tree
    // Properties, read-only (Christian, 2026-09-23 -- the editable half waits
    // for demand). Nothing else in the viewer answers "what is actually in
    // this file", which is the first question a tree raises.
    //
    // Computed FRESH every time it opens rather than cached: the whole of
    // collectBasicTreeProperties costs 7ms on the 13,246-tip H5N1 demo, and a
    // cache would go stale the moment the user re-roots or enters a subtree.
    // It describes what is ON SCREEN, so in a subtree it describes the
    // subtree, and says so.
    //
    // Every value goes in through textContent. Tree names, descriptions and
    // identifiers are file data, and file data never becomes markup.

    function treePropRow(parent, label, value) {
        if (value === null || value === undefined || value === '') {
            return;
        }
        let line = document.createElement('div');
        line.className = 'aptx-dialog-line';
        let k = document.createElement('span');
        k.className = 'aptx-dialog-key';
        k.textContent = label;
        let v = document.createElement('span');
        v.className = 'aptx-dialog-val';
        v.textContent = String(value);
        line.appendChild(k);
        line.appendChild(v);
        parent.appendChild(line);
    }

    function treePropSection(body, title) {
        let h = document.createElement('div');
        h.className = 'aptx-props-head';
        h.textContent = title;
        body.appendChild(h);
        let box = document.createElement('div');
        body.appendChild(box);
        return box;
    }

    function countNumber(n) {
        return (typeof n === 'number' && isFinite(n)) ? n.toLocaleString() : null;
    }

    // A number for a fact row: thousands separators for counts, and enough
    // significant digits for a branch length, which can be 5e-9.
    function statNumber(v, digits) {
        if (typeof v !== 'number' || !isFinite(v)) {
            return null;
        }
        if (v === 0 || (Math.abs(v) >= 0.001 && Math.abs(v) < 1e7)) {
            return String(forester.roundNumber(v, digits === undefined ? 6 : digits));
        }
        return v.toExponential(3);
    }

    // "1,234 of 5,678 tips", the desktop's coverage phrasing.
    function statOf(part, whole, noun) {
        if (!(whole > 0)) {
            return null;
        }
        return countNumber(part) + ' of ' + countNumber(whole) + (noun ? (' ' + noun) : '');
    }

    // n / minimum / median / maximum / mean, the block Christian asked for in
    // place of a histogram. One shape, used for branch lengths and for each
    // kind of support, so the two read the same way.
    function statSpread(box, d, digits) {
        treePropRow(box, 'Minimum', statNumber(d.min, digits));
        treePropRow(box, 'Median', statNumber(d.median, digits));
        treePropRow(box, 'Maximum', statNumber(d.max, digits));
        treePropRow(box, 'Mean', statNumber(d.mean, digits));
    }

    function showTreePropertiesDialog() {
        if (!_root) {
            return;
        }
        let shell = makeDialogShell(TREE_PROPERTIES_DIALOG, 'Tree properties', 420);
        shell.body.classList.add('aptx-props');
        // A description is free text and can be a paragraph, and the coverage
        // section grows with the annotations, so the body scrolls rather than
        // running off the screen.
        shell.body.style.maxHeight = '66vh';
        shell.body.style.overflowY = 'auto';
        let st = forester.treeStatistics(_root);
        let bp = forester.collectBasicTreeProperties(_root);
        let time = forester.timeAxisInfo(_root);
        let phy = _treeData || {};

        // --- what the tree says it is ---------------------------------
        let box = treePropSection(shell.body, 'Tree');
        treePropRow(box, 'Name', phy.name);
        treePropRow(box, 'Description', phy.description);
        if (phy.id && phy.id.value) {
            treePropRow(box, 'Identifier', phy.id.provider
                ? (phy.id.value + '  (' + phy.id.provider + ')') : phy.id.value);
        }
        treePropRow(box, 'Type', phy.type);
        treePropRow(box, 'Branch-length unit', phy.branch_length_unit);
        // Only when the FILE said so. phyloXML has a rooted attribute and a
        // Nexus tree statement has [&R]/[&U]; plain Newick says nothing, and a
        // properties dialog that answered "yes" there would be reporting our
        // writing default as though the file had stated it.
        if (typeof phy.rooted === 'boolean') {
            treePropRow(box, 'Rooted', phy.rooted ? 'yes' : 'no');
        }
        if (typeof phy.rerootable === 'boolean') {
            treePropRow(box, 'Rerootable', phy.rerootable ? 'yes' : 'no');
        }
        if (_trees && _trees.length > 1) {
            treePropRow(box, 'In this file', 'tree ' + (_treeIndex + 1) + ' of ' + _trees.length);
        }
        if (_in_subtree) {
            treePropRow(box, 'Showing', 'a subtree, not the whole tree');
        }
        if (!box.firstChild) {
            treePropRow(box, 'Name', '(the tree carries no name or metadata)');
        }

        // --- shape ----------------------------------------------------
        box = treePropSection(shell.body, 'Structure');
        treePropRow(box, 'Tips', countNumber(st.tips));
        treePropRow(box, 'Internal nodes', countNumber(st.internal));
        treePropRow(box, 'Nodes, total', countNumber(st.nodes));
        treePropRow(box, 'Branches', countNumber(st.branches));
        treePropRow(box, 'Branching', st.polytomies === 0 ? 'fully binary'
            : (countNumber(st.polytomies) + (st.polytomies === 1 ? ' polytomy' : ' polytomies')
                + ', widest ' + countNumber(st.maxChildren) + ' children'));
        treePropRow(box, 'Depth', countNumber(st.depth) + ' (root to deepest tip)');
        // ours, not the desktop's, and worth keeping: the label width is what
        // decides how much room the tree needs, and whether internal nodes are
        // named decides whether their labels are worth turning on
        treePropRow(box, 'Longest tip label', bp.longestNodeName > 0
            ? (countNumber(bp.longestNodeName)
                + (bp.longestNodeName === 1 ? ' character' : ' characters')) : null);
        treePropRow(box, 'Internal nodes named', st.internal > 0
            ? (st.namedInternal > 0 ? statOf(st.namedInternal, st.internal) : 'none') : null);

        // --- branch lengths -------------------------------------------
        box = treePropSection(shell.body, 'Branch lengths');
        if (st.branchLengths) {
            treePropRow(box, 'Branches with a length',
                statOf(st.branchLengths.n, st.branches));
            statSpread(box, st.branchLengths);
            treePropRow(box, 'Sum', statNumber(st.branchLengths.sum) + ' (total tree length)');
            treePropRow(box, 'Height', statNumber(st.height) + ' (root to farthest tip)');
            if (st.branchLengths.zero > 0) {
                treePropRow(box, 'Zero-length', countNumber(st.branchLengths.zero));
            }
            if (st.branchLengths.negative > 0) {
                treePropRow(box, 'Negative', countNumber(st.branchLengths.negative)
                    + ' (not drawn to scale)');
            }
            treePropRow(box, 'Ultrametric', st.ultrametric
                ? 'yes (every tip the same distance from the root)' : 'no');
        } else {
            treePropRow(box, 'Branches with a length', 'none, the tree has no lengths');
        }

        // --- support, one section per kind ----------------------------
        // A bootstrap and a posterior on the same branch are not on one scale,
        // so they are never pooled: each type gets its own n and spread.
        st.support.forEach(function (d) {
            // 'unknown' is what the Newick and Nexus readers put on a bare
            // [95]: those formats have one support slot and nowhere to name
            // what it is, so it is an absence of type rather than a type
            // called unknown, and it should not head a section as one.
            let untyped = !d.type || d.type === 'unknown';
            let title = (st.support.length === 1 && untyped)
                ? 'Support values' : ('Support: ' + (untyped ? 'untyped' : d.type));
            let sbox = treePropSection(shell.body, title);
            treePropRow(sbox, 'Branches with support', statOf(d.n, st.branches));
            statSpread(sbox, d);
        });

        // --- what came with it ----------------------------------------
        box = treePropSection(shell.body, 'The tree carries');
        let carried = 0;
        function carries(label, present, detail) {
            if (!present) {
                return;
            }
            ++carried;
            treePropRow(box, label, detail || 'yes');
        }
        carries('Taxonomies', st.tipsWithTaxonomy > 0, statOf(st.tipsWithTaxonomy, st.tips, 'tips')
            + (st.distinctTaxonomies > 0 ? (', ' + countNumber(st.distinctTaxonomies) + ' distinct') : ''));
        carries('Taxonomy identifiers', st.tipsWithTaxonomyId > 0,
            statOf(st.tipsWithTaxonomyId, st.tips, 'tips'));
        carries('Sequences', st.tipsWithSequence > 0, statOf(st.tipsWithSequence, st.tips, 'tips'));
        // alignedMolSeqs starts TRUE and is only ever set false, so it means
        // "no UNALIGNED sequence was seen" -- a tree carrying no sequences at
        // all reports true. Read alone it told the flu and ammonite demos they
        // had an alignment. Every other reader in this file pairs it with a
        // length for the same reason.
        carries('Molecular sequences', st.tipsWithMolSeq > 0,
            statOf(st.tipsWithMolSeq, st.tips, 'tips')
            + (bp.alignedMolSeqs && bp.maxMolSeqLength > 0
                ? (', aligned, ' + countNumber(bp.maxMolSeqLength) + ' columns') : ''));
        carries('Domain architectures', st.tipsWithDomains > 0,
            statOf(st.tipsWithDomains, st.tips, 'tips')
            + (bp.maxDomainArchitectureLength > 0
                ? (', up to ' + countNumber(bp.maxDomainArchitectureLength) + ' residues') : ''));
        carries('Genome regions', st.tipsWithGenes > 0,
            statOf(st.tipsWithGenes, st.tips, 'tips')
            + (bp.maxGeneRegionLength > 0
                ? (', up to ' + countNumber(bp.maxGeneRegionLength) + ' bp') : ''));
        carries('Dates', st.nodesWithDate > 0, statOf(st.nodesWithDate, st.nodes, 'nodes'));
        carries('Distributions', st.tipsWithDistribution > 0,
            statOf(st.tipsWithDistribution, st.tips, 'tips'));
        carries('MAD values', bp.madValues);
        carries('Branch colours', bp.branchColors);
        if (st.nodesWithEvents > 0) {
            let parts = [];
            if (st.duplications > 0) {
                parts.push(countNumber(st.duplications)
                    + (st.duplications === 1 ? ' duplication' : ' duplications'));
            }
            if (st.speciations > 0) {
                parts.push(countNumber(st.speciations)
                    + (st.speciations === 1 ? ' speciation' : ' speciations'));
            }
            parts.push(statOf(st.nodesWithEvents, st.nodes, 'nodes'));
            carries('Events', true, parts.join(', '));
        }
        st.propertyRefs.forEach(function (r) {
            carries('Metadata ' + r.ref, true, statOf(r.nodes, st.nodes, 'nodes'));
        });
        if (carried === 0) {
            treePropRow(box, 'Annotations', 'none, names and topology only');
        }

        // --- time -----------------------------------------------------
        if (time && (time.type || time.dated)) {
            box = treePropSection(shell.body, 'Time');
            treePropRow(box, 'Dates', time.type === 'geologic'
                ? 'geologic ages' : (time.type === 'calendar' ? 'calendar years' : 'yes'));
            treePropRow(box, 'Dated nodes', statOf(st.nodesWithDate, st.nodes, 'nodes')
                + (time.dated ? ' (a dated tree)' : ''));
            if (time.type === 'geologic' && time.rootAge > 0) {
                treePropRow(box, 'Oldest node', statNumber(time.rootAge, 4) + ' Ma');
            }
            if (time.type === 'calendar' && time.presentDate > 0) {
                treePropRow(box, 'Most recent tip', statNumber(time.presentDate, 4));
            }
            treePropRow(box, 'Confidence intervals',
                (time.hasInternalIntervals || time.hasExternalIntervals) ? 'yes' : null);
        }

        shell.dialog.showModal();
    }

    // ===================== Diagnostics =====================
    // "Dependencies are checked when used, never at load time" makes the
    // viewer hard to break and easy to run half-equipped without knowing: on
    // BV-BRC it ran for weeks with no PDF or PNG export, a retired config key
    // and a forced visualization, and every one of those was found by reading
    // the site's source (Christian, 2026-10-09: a "check engine light" and a
    // doctor behind it). This is the one place that says what is loaded, what
    // that switches off, and what the launch complained about.
    //
    // Two rules decide what is a PROBLEM (lights the dot) and what is only
    // stated:
    //   * an optional library that is simply absent is a site's choice, and
    //     is stated ("PDF export: off"), never flagged;
    //   * something nobody chooses is a problem: half of a pair (jspdf
    //     without svg2pdf.js), a library from the 2.x days under its old
    //     global, a d3 that is not 7, forester.js from another release, a
    //     phyloxml that no longer writes what this release expects, and every
    //     warning or error the launch printed about its config.
    // Only d3, jsPDF and forester state a version, so everything else is
    // judged by what it can do.
    //
    // Nothing in here may throw: every check runs in its own try, and a check
    // that fails says so in its own row.

    // phyloxml states no version, so a small tree goes through it and what
    // comes back is read for what an OLDER release is known to do. Each of
    // these is a named fault, and each published release before 1.1.7 shows
    // at least one (measured on 1.0.2, 1.1.3, 1.1.4, 1.1.5 and 1.1.6):
    //   * it drops the domain architecture, or a <phylogeny>'s own property
    //     (before 1.1.5 / 1.1.3): a saved tree LOSES data;
    //   * it writes a style colour as it came, or the style property before
    //     the node's other properties (before 1.1.7): the saved file differs
    //     from the desktop program's.
    // Whether the output is byte for byte what 1.1.7 writes is looked at too,
    // but a difference there alone is only a NOTE. package.json admits any
    // 1.1.x from 1.1.7 up, a release of this viewer cannot be corrected
    // after it is published, and a newer phyloxml that lays a file out
    // differently must not light a dot on every page that has it. (A first
    // version demanded the bytes and called every difference "an older
    // copy".)
    const PHYLOXML_PROBE_IN = '<phyloxml xmlns="http://www.phyloxml.org"><phylogeny rooted="true"><clade>'
        + '<clade><name>a</name><branch_length>1</branch_length>'
        + '<sequence><domain_architecture length="9"><domain from="1" to="5" confidence="0.1">D</domain>'
        + '</domain_architecture></sequence>'
        + '<property ref="style:font_color" datatype="xsd:token" applies_to="node">#CE1616</property>'
        + '<property ref="x:y" datatype="xsd:string" applies_to="node">v</property></clade>'
        + '<clade><name>b</name><branch_length>2</branch_length></clade></clade>'
        + '<property ref="p:q" datatype="xsd:string" applies_to="phylogeny">w</property></phylogeny></phyloxml>';
    const PHYLOXML_PROBE_OUT = ['<?xml version="1.0" encoding="UTF-8"?>',
        '<phyloxml xmlns="http://www.phyloxml.org">',
        '<phylogeny rooted="true" rerootable="true">',
        '  <clade>',
        '    <clade>',
        '      <name>a</name>',
        '      <branch_length>1</branch_length>',
        '      <sequence>',
        '        <domain_architecture length="9">',
        '          <domain from="1" to="5" confidence="0.1">D</domain>',
        '        </domain_architecture>',
        '      </sequence>',
        '      <property ref="x:y" datatype="xsd:string" applies_to="node">v</property>',
        '      <property ref="style:font_color" datatype="xsd:token" applies_to="node">#ce1616</property>',
        '    </clade>',
        '    <clade>',
        '      <name>b</name>',
        '      <branch_length>2</branch_length>',
        '    </clade>',
        '  </clade>',
        '  <property ref="p:q" datatype="xsd:string" applies_to="phylogeny">w</property>',
        '</phylogeny>',
        '</phyloxml>'].join('\n');
    const PHYLOXML_EXPECTED = '1.1.7';
    const D3_TESTED_MINOR = 9;       // package.json: d3 ^7.9.0
    const JSPDF_TESTED_MAJOR = 4;    // package.json: jspdf ^4.2.1

    // The probe's answer for the library object it was asked about: the
    // dot asks often, and the answer cannot change.
    //   threw / stage   reading ('read') or writing ('write') failed, with the message
    //   lost            what a saved tree no longer has
    //   old             what is written as releases before 1.1.7 wrote it
    //   same            the output is byte for byte 1.1.7's
    let _phyloXmlProbe = null;
    function probePhyloXml(px) {
        if (_phyloXmlProbe && _phyloXmlProbe.lib === px) {
            return _phyloXmlProbe.result;
        }
        let result = {threw: null, stage: null, lost: [], old: [], same: false};
        let message = function (e) {
            return String(e && e.message ? e.message : e);
        };
        let tree = null;
        try {
            tree = px.parse(PHYLOXML_PROBE_IN, {trim: true, normalize: true})[0];
        } catch (e) {
            result.threw = message(e);
            result.stage = 'read';
        }
        let written = null;
        if (!result.threw) {
            try {
                written = String(px.toPhyloXML(tree, 9));
            } catch (e) {
                result.threw = message(e);
                result.stage = 'write';
            }
        }
        if (written !== null) {
            result.same = written === PHYLOXML_PROBE_OUT;
            if (!/<domain from="1" to="5"[^>]*>D<\/domain>/.test(written)) {
                result.lost.push('protein domains');
            }
            if (written.indexOf('ref="p:q"') < 0) {
                result.lost.push('a tree\'s own properties');
            }
            if (written.indexOf('ref="x:y"') < 0) {
                result.lost.push('node properties');
            }
            let style = written.indexOf('ref="style:font_color"');
            if (style < 0) {
                result.lost.push('node styles');
            } else {
                if (written.indexOf('>#ce1616<') < 0) {
                    result.old.push('a style colour as it came, not in lower case');
                }
                if (written.indexOf('ref="x:y"') > style) {
                    result.old.push('a node\'s style before its other properties');
                }
            }
        }
        _phyloXmlProbe = {lib: px, result: result};
        return result;
    }

    // One library's row. `judge` returns {loaded, version, status, detail};
    // status is 'ok', 'absent' (optional and not there: stated), 'note' or
    // 'problem'.
    function doctorLibrary(name, role, judge) {
        let row = {name: name, role: role, loaded: false, version: null, status: 'problem', detail: ''};
        try {
            let j = judge();
            row.loaded = !!j.loaded;
            row.version = j.version || null;
            row.status = j.status;
            row.detail = j.detail || '';
        } catch (e) {
            row.detail = 'this check failed: ' + (e && e.message ? e.message : e);
        }
        return row;
    }

    function doctorLibraries() {
        let g = root || {};
        // without a document there is nothing to launch into: the parsers
        // work with no d3 at all, so its absence there is not a fault
        let inBrowser = typeof g.document !== 'undefined';
        let libs = [];

        libs.push(doctorLibrary('forester.js', 'required', function () {
            let f = forester || g.forester;
            if (!f) {
                return {loaded: false, status: 'problem', detail: 'not loaded: nothing can be read or drawn'};
            }
            if (f.VERSION === VERSION) {
                return {loaded: true, version: f.VERSION, status: 'ok'};
            }
            return {loaded: true, version: f.VERSION || null, status: 'problem',
                detail: (f.VERSION ? 'forester.js is ' + f.VERSION : 'forester.js states no version, so it is an older file')
                    + ', archaeopteryx.js is ' + VERSION + ': the two must come from the same release'};
        }));

        libs.push(doctorLibrary('d3', 'required', function () {
            // THE d3 THE VIEWER USES, chosen as requireD3 chooses it: the one
            // it was handed at load, and the page's global only where that
            // one is missing or unusable. (A first version looked at the
            // global first and could report on a d3 nothing was drawn with.)
            let d = (g.d3 && (!d3 || typeof d3.zoom !== 'function')) ? g.d3 : d3;
            if (!d) {
                return inBrowser
                    ? {loaded: false, status: 'problem', detail: 'not loaded: launch() fails without d3 version 7'}
                    : {loaded: false, status: 'absent', detail: 'not loaded: only launch() needs it'};
            }
            let usable = typeof d.zoom === 'function' && typeof d.cluster === 'function';
            let version = typeof d.version === 'string' ? d.version : null;
            if (version === null) {
                // d3's ES-module build exports no `version`: a bundler's
                // `import * as d3`, jsdelivr's +esm, Node's require('d3'). It
                // is judged by what only d3 7 has -- InternMap arrived with
                // d3-array 3, which is d3 7.0.0 -- and never called outdated
                // for not saying its number.
                if (usable && typeof d.InternMap === 'function') {
                    return {loaded: true, status: 'ok', detail: 'states no version (an ES-module build); has what d3 7 has'};
                }
                return {loaded: true, status: inBrowser ? 'problem' : 'absent',
                    detail: inBrowser ? 'states no version and lacks what d3 7 has: Archaeopteryx.js needs d3 version 7'
                        : 'not usable here as d3 version 7: only launch() needs it'};
            }
            let parts = version.split('.').map(Number);
            if (parts[0] !== 7 || !usable) {
                return {loaded: true, version: version, status: inBrowser ? 'problem' : 'absent',
                    detail: inBrowser ? 'Archaeopteryx.js needs d3 version 7'
                        : 'not usable here as d3 version 7: only launch() needs it'};
            }
            if (parts[1] < D3_TESTED_MINOR) {
                return {loaded: true, version: version, status: 'note',
                    detail: 'older than the 7.' + D3_TESTED_MINOR + ' this release is tested with'};
            }
            return {loaded: true, version: version, status: 'ok'};
        }));

        let px = null;
        let probe = null;
        libs.push(doctorLibrary('phyloxml', 'required', function () {
            px = phyloXml || g.phyloXml;
            probe = px ? probePhyloXml(px) : null;
            if (!px) {
                return {loaded: false, status: 'problem',
                    detail: 'not loaded: phyloXML cannot be read, and the phyloXML download fails'};
            }
            if (probe.threw) {
                // on a page phyloxml takes sax from the global, and a missing
                // one is the usual reason reading fails; anywhere else, and
                // for any other failure, the message itself is the finding
                return {loaded: true, status: 'problem', detail: (probe.stage === 'read' && inBrowser && !g.sax)
                    ? 'cannot read phyloXML: sax.js is not loaded'
                    : (probe.stage === 'read' ? 'reading' : 'writing') + ' a small tree failed: ' + probe.threw};
            }
            if (probe.lost.length > 0) {
                return {loaded: true, status: 'problem', detail: 'an older copy: saving a tree as phyloXML drops '
                    + probe.lost.join(', ') + ' (phyloxml ' + PHYLOXML_EXPECTED + ' keeps them)'};
            }
            if (probe.old.length > 0) {
                return {loaded: true, status: 'problem', detail: 'an older copy: it writes ' + probe.old.join(', and ')
                    + ', so a saved tree differs from the desktop program\'s file (phyloxml ' + PHYLOXML_EXPECTED
                    + ' does not)'};
            }
            if (!probe.same) {
                return {loaded: true, status: 'note', detail: 'writes a small tree differently from phyloxml '
                    + PHYLOXML_EXPECTED + ', losing nothing: a newer release, or an altered copy'};
            }
            return {loaded: true, status: 'ok', detail: 'writes phyloXML as ' + PHYLOXML_EXPECTED + ' does'};
        }));
        libs.push(doctorLibrary('sax', 'required', function () {
            // A page hands sax over as a global. Anywhere else (Node, a
            // bundler) phyloxml gets it by require() when it loads, so a
            // phyloxml that loaded has it, and a tree it read proves it.
            if (g.sax || (probe && probe.stage !== 'read')) {
                return {loaded: true, status: 'ok'};
            }
            if (!inBrowser && px) {
                return {loaded: true, status: 'ok', detail: 'taken by phyloxml when it loaded'};
            }
            return {loaded: false, status: 'problem', detail: 'not loaded: phyloxml needs it to read phyloXML'};
        }));

        libs.push(doctorLibrary('canvg', 'optional', function () {
            if (g.Canvg && typeof g.Canvg.fromString === 'function') {
                return {loaded: true, status: 'ok'};
            }
            if (g.Canvg) {
                return {loaded: true, status: 'problem',
                    detail: 'window.Canvg has no fromString: not canvg 4, so PNG export is off'};
            }
            if (g.canvg) {
                return {loaded: true, status: 'problem', detail: 'loaded under its old global "canvg" (canvg 1 to 3);'
                    + ' PNG export needs canvg 4 as window.Canvg, so it is off'};
            }
            return {loaded: false, status: 'absent', detail: 'not loaded: PNG export and Copy PNG are off'};
        }));

        // The pair is read inside each row's own guard: whatever a page has
        // put under these names, a lookup that throws costs its row and no
        // other.
        let pdfPair = function () {
            let J = g.jspdf && g.jspdf.jsPDF;
            return {J: J, attached: !!(J && J.API && J.API.svg), svg2pdf: !!g.svg2pdf};
        };
        libs.push(doctorLibrary('jspdf', 'optional', function () {
            let pair = pdfPair();
            let J = pair.J;
            let attached = pair.attached;
            if (J) {
                let version = typeof J.version === 'string' ? J.version : null;
                if (!attached && !g.svg2pdf) {
                    return {loaded: true, version: version, status: 'problem',
                        detail: 'loaded without svg2pdf.js: PDF export needs both, so it is off'};
                }
                if (version && Number(version.split('.')[0]) !== JSPDF_TESTED_MAJOR) {
                    return {loaded: true, version: version, status: 'note',
                        detail: 'this release is tested with jspdf ' + JSPDF_TESTED_MAJOR};
                }
                return {loaded: true, version: version, status: 'ok'};
            }
            if (g.jsPDF) {
                return {loaded: true, status: 'problem', detail: 'loaded under its old global "jsPDF" (jsPDF 1);'
                    + ' PDF export needs jspdf ' + JSPDF_TESTED_MAJOR + ' as window.jspdf, so it is off'};
            }
            return {loaded: false, status: 'absent', detail: 'not loaded: PDF export is off'};
        }));
        libs.push(doctorLibrary('svg2pdf.js', 'optional', function () {
            let pair = pdfPair();
            let J = pair.J;
            let attached = pair.attached;
            if (attached) {
                return {loaded: true, status: 'ok'};
            }
            if (g.svg2pdf && J) {
                return {loaded: true, status: 'problem', detail: 'loaded, but not attached to jspdf (jsPDF.API.svg'
                    + ' is missing): load jspdf first. PDF export is off'};
            }
            if (g.svg2pdf) {
                return {loaded: true, status: 'problem',
                    detail: 'loaded without jspdf: PDF export needs both, so it is off'};
            }
            return {loaded: false, status: 'absent',
                detail: J ? 'not loaded' : 'not loaded: PDF export is off'};
        }));
        return libs;
    }

    // What the user gets or does not get, each with the reason.
    function doctorFunctions(libs) {
        let lib = function (name) {
            return libs.find(function (l) {
                return l.name === name;
            });
        };
        let inBrowser = typeof window !== 'undefined' && typeof document !== 'undefined';
        let fn = function (name, test, whyNot) {
            let available = false;
            let detail = '';
            try {
                available = inBrowser && !!test();
                detail = available ? '' : (inBrowser ? whyNot() : 'needs a browser');
            } catch (e) {
                detail = 'this check failed: ' + (e && e.message ? e.message : e);
            }
            return {name: name, available: available, detail: detail};
        };
        // why a function is off, in the library's name: its row's reason
        // reads "not loaded: ..." under its own name and needs the subject here
        let why = function (l) {
            return l.status === 'absent' ? l.name + ' is not loaded' : l.name + ': ' + l.detail;
        };
        let out = [];
        try {
            // ON whenever phyloxml reads and writes at all -- which is what
            // the Download menu's phyloXML entry does, and it is always
            // offered. An older copy still works: its row above says what a
            // saved file loses, and this row repeats it without turning off.
            let px = lib('phyloxml');
            let works = px.loaded && !/(cannot read phyloXML|a small tree failed|this check failed)/.test(px.detail);
            out.push({name: 'Read and save phyloXML', available: works,
                detail: px.status === 'ok' ? '' : (works ? px.detail : why(px))});
        } catch (e) {
            out.push({name: 'Read and save phyloXML', available: false,
                detail: 'this check failed: ' + (e && e.message ? e.message : e)});
        }
        out.push(fn('PNG export', pngExportAvailable, function () {
            return why(lib('canvg'));
        }));
        out.push(fn('Copy PNG', pngCopyAvailable, function () {
            if (!pngExportAvailable()) {
                return why(lib('canvg'));
            }
            return window.isSecureContext ? 'this browser cannot write an image to the clipboard'
                : 'needs a secure page (https, or localhost)';
        }));
        out.push(fn('PDF export', pdfExportAvailable, function () {
            let pair = [lib('jspdf'), lib('svg2pdf.js')];
            let bad = pair.find(function (l) {
                return l.status === 'problem';
            });
            if (bad) {
                return why(bad);
            }
            return pair.every(function (l) {
                return l.status === 'absent';
            }) ? 'jspdf and svg2pdf.js are not loaded' : why(pair.find(function (l) {
                return l.status !== 'ok';
            }) || pair[0]);
        }));
        return out;
    }

    // A config value as one short word or number: enough to see what a site
    // passed, never the value itself where that could be a tree or a callback.
    function doctorConfigValue(v) {
        if (v === null || typeof v === 'boolean' || typeof v === 'number') {
            return v;
        }
        if (typeof v === 'string') {
            return v.length > 80 ? v.substring(0, 77) + '...' : v;
        }
        if (typeof v === 'function') {
            return '(function)';
        }
        if (Array.isArray(v)) {
            return '(list of ' + v.length + ')';
        }
        return '(' + typeof v + ')';
    }

    // The tree on view, as noted when its launch took the page over
    // (_onView): null until one has, so a first launch that was rejected
    // describes no tree. The tip count is the one the launch computed.
    function doctorLaunch() {
        if (!_onView) {
            return null;
        }
        let launch = {config: {}, tips: null, tree: _onView.tree, trees: _onView.trees, container: null};
        try {
            Object.keys(_onView.config || {}).sort().forEach(function (k) {
                launch.config[k] = doctorConfigValue(_onView.config[k]);
            });
        } catch {
            launch.config = {};
        }
        launch.tips = (typeof _onView.tips === 'number') ? _onView.tips : null;
        try {
            launch.container = {width: _onView.container.clientWidth, height: _onView.container.clientHeight};
        } catch {
            launch.container = null;
        }
        return launch;
    }

    function doctorText(rep) {
        let pad = function (text, n) {
            text = String(text);
            return text + ' '.repeat(Math.max(1, n - text.length));
        };
        let lines = [NAME + ' ' + rep.version + ' diagnostics', ''];
        lines.push('Status: ' + rep.summary);
        rep.problems.forEach(function (p) {
            lines.push('  ! ' + p);
        });
        lines.push('', 'Libraries');
        rep.libraries.forEach(function (l) {
            lines.push('  ' + pad(l.name, 13) + pad(l.version || (l.loaded ? 'loaded' : 'not loaded'), 12)
                + pad(l.status === 'absent' ? l.role : l.status, 9) + l.detail);
        });
        lines.push('', 'Functions');
        rep.functions.forEach(function (f) {
            lines.push('  ' + pad(f.name, 24) + (f.available ? 'on' : 'off') + (f.detail ? '   ' + f.detail : ''));
        });
        if (rep.notes.length > 0) {
            lines.push('', 'Notes');
            rep.notes.forEach(function (n) {
                lines.push('  - ' + n);
            });
        }
        lines.push('', 'Launch');
        if (rep.launch) {
            lines.push('  config: ' + JSON.stringify(rep.launch.config));
            if (rep.launch.tips !== null) {
                lines.push('  tree: ' + rep.launch.tips + ' tips' + (rep.launch.trees > 1
                    ? ' (tree ' + rep.launch.tree + ' of ' + rep.launch.trees + ')' : ''));
            }
            if (rep.launch.container) {
                lines.push('  container: ' + rep.launch.container.width + ' x ' + rep.launch.container.height + ' px');
            }
        } else {
            lines.push('  no tree is on view');
        }
        lines.push('', 'Environment');
        lines.push('  ' + (rep.environment.userAgent || 'no browser'));
        if (rep.environment.secureContext !== null) {
            lines.push('  secure page: ' + (rep.environment.secureContext ? 'yes' : 'no'));
        }
        return lines.join('\n');
    }

    // The problems and the notes: the libraries' and what the launch said.
    // This is all the dot needs, so it is kept apart from the report, which
    // also works out the functions, the launch section and the text.
    function doctorFindings() {
        let libs;
        try {
            libs = doctorLibraries();
        } catch (e) {
            libs = [{name: 'libraries', role: 'required', loaded: false, version: null, status: 'problem',
                detail: 'the checks failed: ' + (e && e.message ? e.message : e)}];
        }
        let problems = [];
        let notes = [];
        libs.forEach(function (l) {
            if (l.status === 'problem') {
                problems.push(l.name + ': ' + l.detail);
            } else if (l.status === 'note') {
                notes.push(l.name + (l.version ? ' ' + l.version : '') + ': ' + l.detail);
            }
        });
        _diagnostics.forEach(function (d) {
            (d.level === 'problem' ? problems : notes).push(d.text + (d.count > 1 ? ' (' + d.count + ' times)' : ''));
        });
        return {libraries: libs, problems: problems, notes: notes,
            summary: problems.length === 0 ? 'nothing to report'
                : problems.length + (problems.length === 1 ? ' thing' : ' things') + ' to check'};
    }

    function doctorReport() {
        let found = doctorFindings();
        let libs = found.libraries;
        let problems = found.problems;
        let notes = found.notes;
        let functions;
        try {
            functions = doctorFunctions(libs);
        } catch {
            functions = [];
        }
        let launch = null;
        try {
            launch = doctorLaunch();
        } catch {
            launch = null;
        }
        let nav = (typeof navigator !== 'undefined') ? navigator : null;
        let rep = {
            program: NAME,
            version: VERSION,
            ok: problems.length === 0,
            summary: found.summary,
            problems: problems,
            notes: notes,
            libraries: libs,
            functions: functions,
            launch: launch,
            environment: {
                userAgent: nav && nav.userAgent ? nav.userAgent : null,
                secureContext: (typeof window !== 'undefined' && typeof window.isSecureContext === 'boolean')
                    ? window.isSecureContext : null
            }
        };
        try {
            rep.text = doctorText(rep);
        } catch (e) {
            rep.text = NAME + ' ' + VERSION + ' diagnostics: the report could not be written ('
                + (e && e.message ? e.message : e) + ')';
        }
        return rep;
    }

    /**
     * The state of the program on this page: which libraries are loaded (and
     * their versions, where a library states one), which functions that
     * switches off, and what the last launch() warned about. Works before a
     * launch and after a failed one, and in Node. Never throws.
     *
     * @returns {{program: string, version: string, ok: boolean, summary: string,
     *   problems: string[], notes: string[], libraries: Object[], functions: Object[],
     *   launch: Object|null, environment: Object, text: string}} `ok` is false when
     *   something is wrong that nobody chooses (see README "Diagnostics");
     *   `text` is the whole report as plain text, for pasting into an issue.
     */
    archaeopteryx.doctor = function () {
        let rep = doctorReport();
        syncDoctorDot();   // whoever asks sees a dot that agrees with the answer
        return rep;
    };

    // The "check engine light": a small dot after the program name in the
    // panel header, there only while the report has a problem. Neutral, not
    // a warning colour: the people who see it are mostly the site's users,
    // who can do nothing about it, and it is for the one who can.
    //
    // What a page has loaded can change under a viewer that is already up (a
    // library arriving late, a script replacing a global) and nothing
    // announces it, so the dot is brought up to date whenever it could be
    // looked at or asked about: when a problem is recorded, when the header
    // is built, when the page finishes loading, when the pointer enters the
    // panel, when the About box opens and when doctor() is called.
    function syncDoctorDot() {
        try {
            let host = _onView && _onView.container;
            if (!host || typeof host.querySelector !== 'function') {
                return;
            }
            let button = host.querySelector('.aptx-panel .' + PROGNAMELINK);
            let dot = button && button.querySelector('.aptx-doctor-dot');
            if (!dot) {
                return;
            }
            let found = doctorFindings();
            let ok = found.problems.length === 0;
            dot.hidden = ok;
            button.title = 'About ' + NAME + (ok ? '' : ': ' + found.summary);
        } catch {
            // a light that cannot be lit must not take the viewer with it
        }
    }

    function showDoctorDialog() {
        let rep = doctorReport();
        let shell = makeDialogShell(DOCTOR_DIALOG, 'Diagnostics', 500);
        shell.body.classList.add('aptx-doctor');

        // The summary and Copy report share the first line: the report is
        // longer than a small window, and the one button must not be the
        // thing scrolled out of sight.
        let head = document.createElement('div');
        head.className = 'aptx-doctor-head';
        let status = document.createElement('div');
        status.className = 'aptx-doctor-status' + (rep.ok ? '' : ' aptx-doctor-bad');
        status.textContent = NAME + ' ' + rep.version + ': ' + rep.summary;
        let copy = document.createElement('button');
        copy.type = 'button';
        copy.className = 'aptx-reps-button aptx-doctor-copy';
        copy.textContent = 'Copy report';
        copy.title = 'copy this report as text, with the launch configuration and the browser added,'
            + ' to paste into an issue or an e-mail';
        copy.addEventListener('click', function () {
            copyText(rep.text, shell.dialog).then(function (ok) {
                flashButton(copy, ok ? 'Copied \u2713' : 'Copy failed');
            });
        });
        head.appendChild(status);
        head.appendChild(copy);
        shell.body.appendChild(head);

        let list = function (items, cls) {
            items.forEach(function (text) {
                let item = document.createElement('div');
                item.className = 'aptx-doctor-item ' + cls;
                item.textContent = text;   // may quote a config value: never markup
                shell.body.appendChild(item);
            });
        };
        let section = function (title) {
            let h = document.createElement('div');
            h.className = 'aptx-doctor-section';
            h.textContent = title;
            shell.body.appendChild(h);
        };
        let row = function (key, value, detail, bad) {
            let line = document.createElement('div');
            line.className = 'aptx-dialog-line' + (bad ? ' aptx-doctor-bad' : '');
            let k = document.createElement('span');
            k.className = 'aptx-dialog-key';
            k.textContent = key;
            let v = document.createElement('span');
            v.className = 'aptx-dialog-val';
            let main = document.createElement('span');
            main.className = 'aptx-doctor-value';
            main.textContent = value;
            v.appendChild(main);
            if (detail) {
                let d = document.createElement('span');
                d.className = 'aptx-doctor-detail';
                d.textContent = detail;
                v.appendChild(d);
            }
            line.appendChild(k);
            line.appendChild(v);
            shell.body.appendChild(line);
        };
        list(rep.problems, 'aptx-doctor-bad');

        section('Libraries');
        rep.libraries.forEach(function (l) {
            // "not loaded" is the value: a reason that opens with the same
            // two words and a colon does not say them again. (Only that
            // exact opening: "loaded, but not attached..." keeps its start.)
            let value = l.version || (l.loaded ? 'loaded' : 'not loaded');
            let detail = l.detail === value ? ''
                : (l.detail.indexOf('not loaded: ') === 0 && value === 'not loaded' ? l.detail.substring(12) : l.detail);
            row(l.name, value, detail, l.status === 'problem');
        });
        section('Functions');
        rep.functions.forEach(function (f) {
            row(f.name, f.available ? 'on' : 'off', f.detail, false);
        });
        if (rep.notes.length > 0) {
            section('Notes');
            list(rep.notes, 'aptx-doctor-note');
        }

        shell.dialog.showModal();
    }

